from rich.prompt import Prompt

def test_case_sensitive():
    print("Testing case-sensitive (default)...")
    p = Prompt("Name", choices=["Paul"])
    try:
        print(f"Check 'paul' in ['Paul'] (case_sensitive=True): {p.check_choice('paul')}")
    except AttributeError:
        print("AttributeError: case_sensitive not yet implemented")

def test_case_insensitive():
    print("\nTesting case-insensitive...")
    p = Prompt("Name", choices=["Paul"])
    try:
        p.case_sensitive = False
        print(f"Check 'paul' in ['Paul'] (case_sensitive=False): {p.check_choice('paul')}")
    except AttributeError:
        print("AttributeError: case_sensitive not yet implemented")

if __name__ == "__main__":
    test_case_sensitive()
    test_case_insensitive()

